import {gpuFn} from './gpu-function-scope.js';
import * as T from 'three/tsl';

const angle=gpuFn(([incident,center,candidate,ratio,reflection])=>{const a=reflection.select(incident.reflect(center),incident.refract(center,ratio)).toVar(),b=reflection.select(incident.reflect(candidate),incident.refract(candidate,ratio)).toVar(),result=T.float(1.57).toVar();T.If(a.dot(a).greaterThanEqual(.000001).and(b.dot(b).greaterThanEqual(.000001)),()=>{a.assign(a.normalize());b.assign(b.normalize());const cosine=a.dot(b).toVar();T.If(cosine.greaterThan(0),()=>{const t=a.cross(b).length().div(cosine.add(1)).toVar();t.divAssign(T.sqrt(t.mul(t).add(1)).add(1));t.divAssign(T.sqrt(t.mul(t).add(1)).add(1));const z=t.mul(t),polynomial=z.mul(-1/15).add(1/13).mul(z).sub(1/11).mul(z).add(1/9).mul(z).sub(1/7).mul(z).add(1/5).mul(z).sub(1/3).mul(z).add(1);result.assign(t.mul(polynomial).mul(8).min(1.57));});});return reflection.not().and(ratio.equal(1)).and(incident.dot(center).lessThan(0)).and(incident.dot(candidate).lessThan(0)).select(T.float(0),result);}).setLayout({name:'hbRayNormalAngle',type:'float',inputs:[{name:'incident',type:'vec3'},{name:'center',type:'vec3'},{name:'candidate',type:'vec3'},{name:'ratio',type:'float'},{name:'reflection',type:'bool'}]});
export const normalDirectionAngleGPU=(...args)=>angle(...args);
export function normalFootprintGPU(transport,u,mode,previous=false){
 if(!mode)return ()=>T.float(0);const{ray,load}=transport;
 return gpuFn(([id,point,view,width,center,ratio,reflection,coat])=>{const result=T.float(0).toVar(),mapped=T.bool(false).toVar(),at=ray.attributes(id).toVar();T.If(at.greaterThan(0),()=>{const material=load(at.add(1)).z;T.If(coat,()=>{if(ray.coatNormalEnabled!==false)mapped.assign(load(at.add(1)).w.greaterThan(9.5).and(load(material.add(19)).z.greaterThan(.5)));}).Else(()=>{if(ray.normalEnabled!==false)mapped.assign(load(material.add(7)).z.greaterThan(.5));});});T.If(width.greaterThan(0).and(mode===1?mapped.not():T.bool(true)),()=>{const facing=ray.geometric(id).dot(view).greaterThan(0).select(1,-1);T.Loop({start:0,end:2,type:'int',name:previous?'priorNormalAxis':'normalAxis'},({[previous?'priorNormalAxis':'normalAxis']:axis})=>{const offset=ray.offset(id,view,width,T.float(axis)).toVar(),normal=T.vec3(0).toVar();if(mode===2)T.If(mapped,()=>{T.If(coat,()=>{normal.assign(previous?ray.coatNormalTime(id,point.add(offset),view,width,u.forward.w):ray.coatNormal(id,point.add(offset),view,width));}).Else(()=>{normal.assign(previous?ray.normalTime(id,point.add(offset),view,width,u.forward.w):ray.normal(id,point.add(offset),view,width));});}).Else(()=>{normal.assign(ray.smoothNormalOffset(id,point,offset));});else normal.assign(ray.smoothNormalOffset(id,point,offset));result.assign(T.max(result,angle(view.negate(),center.mul(facing),normal.mul(facing),ratio,reflection)));});});return result;}).setLayout({name:previous?'hbRayPreviousNormalFootprint':'hbRayNormalFootprint',type:'float',inputs:[{name:'id',type:'float'},{name:'point',type:'vec3'},{name:'view',type:'vec3'},{name:'width',type:'float'},{name:'center',type:'vec3'},{name:'ratio',type:'float'},{name:'reflection',type:'bool'},{name:'coat',type:'bool'}]});
}
